extends RefCounted

var _generations: Array[int] = []
var _free_slots: Array[int] = []
var _entity_data: Dictionary = {} # entity_id -> {type: data}

const INDEX_SHIFT = 32
const GENERATION_MASK = 0xFFFFFFFF

func _get_entity_data(entity: int) -> Dictionary:
    return _entity_data.get(entity, {})

func create_entity() -> int:
    var index: int
    var gen: int
    if _free_slots.size() > 0:
        index = _free_slots.pop_back()
        gen = _generations[index]
    else:
        index = _generations.size()
        _generations.append(1)
        gen = 1

    var handle = (index << INDEX_SHIFT) | gen
    _entity_data[handle] = {}
    return handle

func destroy_entity(entity: int) -> bool:
    if not is_alive(entity):
        return false

    var index = get_index(entity)
    _entity_data.erase(entity)
    _generations[index] += 1
    _free_slots.append(index)
    return true

func is_alive(entity: int) -> bool:
    var index = get_index(entity)
    if index < 0 or index >= _generations.size():
        return false
    return get_generation(entity) == _generations[index]

func get_index(entity: int) -> int:
    return entity >> INDEX_SHIFT

func get_generation(entity: int) -> int:
    return entity & GENERATION_MASK

func add_component(entity: int, component_type: StringName, data: Dictionary) -> bool:
    if not is_alive(entity):
        return false
    _entity_data[entity][component_type] = data
    return true

func remove_component(entity: int, component_type: StringName) -> bool:
    if not is_alive(entity) or not _entity_data[entity].has(component_type):
        return false
    _entity_data[entity].erase(component_type)
    return true

func has_component(entity: int, component_type: StringName) -> bool:
    return is_alive(entity) and _entity_data[entity].has(component_type)

func get_component(entity: int, component_type: StringName) -> Variant:
    if not is_alive(entity):
        return null
    return _entity_data[entity].get(component_type)

func get_component_types(entity: int) -> Variant:
    if not is_alive(entity):
        return null
    var types = _entity_data[entity].keys()
    types.sort()
    return types

func query(required_types: Array) -> Array:
    var result = []
    for entity in _entity_data:
        if not is_alive(entity):
            continue

        var entity_types = _entity_data[entity]
        var match = true
        for type in required_types:
            if not entity_types.has(type):
                match = false
                break
        if match:
            result.append(entity)

    result.sort_custom(func(a, b): return get_index(a) < get_index(b))
    return result

func get_entities_with_exact_types(types: Array) -> Array:
    var result = []
    var required_set = {}
    for t in types:
        required_set[t] = true

    for entity in _entity_data:
        if not is_alive(entity):
            continue

        var entity_types = _entity_data[entity]
        if entity_types.size() != required_set.size():
            continue

        var match = true
        for t in entity_types:
            if not required_set.has(t):
                match = false
                break
        if match:
            result.append(entity)

    result.sort_custom(func(a, b): return get_index(a) < get_index(b))
    return result

